package engine

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/tylergannon/tractor/harness"
)

type runManifest struct {
	ID            string    `json:"id"`
	Name          string    `json:"name"`
	Goal          string    `json:"goal"`
	StartedAt     time.Time `json:"started_at"`
	ControlSocket string    `json:"control_socket"`
}

type activeExecution struct {
	nodeID   string
	nodeType string
	stageDir string
}

type controlServer struct {
	server        *http.Server
	socketPath    string
	temporaryRoot string
}

func (r *Runner) startControlServer(store *runStore) (*controlServer, runManifest, error) {
	socketPath := filepath.Join(store.root, "control.sock")
	temporaryRoot := ""
	if len(socketPath) >= 100 {
		var err error
		temporaryRoot, err = os.MkdirTemp("", "tractor-control-")
		if err != nil {
			return nil, runManifest{}, fmt.Errorf("create control socket directory: %w", err)
		}
		socketPath = filepath.Join(temporaryRoot, "control.sock")
	}
	if err := os.Remove(socketPath); err != nil && !os.IsNotExist(err) {
		if temporaryRoot != "" {
			_ = os.RemoveAll(temporaryRoot)
		}
		return nil, runManifest{}, fmt.Errorf("remove stale control socket: %w", err)
	}
	listener, err := net.Listen("unix", socketPath)
	if err != nil {
		if temporaryRoot != "" {
			_ = os.RemoveAll(temporaryRoot)
		}
		return nil, runManifest{}, fmt.Errorf("listen on control socket: %w", err)
	}

	manifest, err := r.loadOrCreateManifest(socketPath)
	if err != nil {
		_ = listener.Close()
		_ = os.Remove(socketPath)
		if temporaryRoot != "" {
			_ = os.RemoveAll(temporaryRoot)
		}
		return nil, runManifest{}, err
	}
	server := &http.Server{Handler: http.HandlerFunc(func(response http.ResponseWriter, request *http.Request) {
		r.serveControl(store, response, request)
	})}
	control := &controlServer{server: server, socketPath: socketPath, temporaryRoot: temporaryRoot}
	go func() {
		if serveErr := server.Serve(listener); serveErr != nil && !errors.Is(serveErr, http.ErrServerClosed) {
			return
		}
	}()
	return control, manifest, nil
}

func (r *Runner) loadOrCreateManifest(socketPath string) (runManifest, error) {
	path := filepath.Join(r.config.LogsRoot, "manifest.json")
	manifest := runManifest{}
	if raw, err := os.ReadFile(path); err == nil {
		if err := json.Unmarshal(raw, &manifest); err != nil {
			return runManifest{}, fmt.Errorf("decode run manifest: %w", err)
		}
	} else if !os.IsNotExist(err) {
		return runManifest{}, fmt.Errorf("read run manifest: %w", err)
	}
	if manifest.ID == "" {
		id, err := newRunID()
		if err != nil {
			return runManifest{}, err
		}
		manifest.ID = id
		manifest.StartedAt = time.Now().UTC()
	}
	manifest.Name = r.graph.Name
	manifest.Goal = r.graph.Goal
	manifest.ControlSocket = socketPath
	if err := writeJSON(path, manifest); err != nil {
		return runManifest{}, fmt.Errorf("write run manifest: %w", err)
	}
	return manifest, nil
}

func newRunID() (string, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate run ID: %w", err)
	}
	return hex.EncodeToString(value[:]), nil
}

func (r *Runner) serveControl(store *runStore, response http.ResponseWriter, request *http.Request) {
	if request.URL.Path != "/steer" {
		response.WriteHeader(http.StatusNotFound)
		return
	}
	if request.Method != http.MethodPost {
		response.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	decoder := json.NewDecoder(request.Body)
	decoder.DisallowUnknownFields()
	var parts []harness.ContentPart
	if err := decoder.Decode(&parts); err != nil || harness.ValidateContentParts(parts) != nil {
		response.WriteHeader(http.StatusBadRequest)
		return
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		response.WriteHeader(http.StatusBadRequest)
		return
	}

	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	if r.active == nil || r.active.stageDir == "" || r.active.nodeType == "parallel" || r.config.Backend == nil {
		response.WriteHeader(http.StatusConflict)
		return
	}
	if r.config.Backend.Steer(parts) != harness.SteerAccepted {
		response.WriteHeader(http.StatusConflict)
		return
	}
	if err := store.appendSteering(r.active.stageDir, parts); err != nil {
		response.WriteHeader(http.StatusInternalServerError)
		return
	}
	response.WriteHeader(http.StatusOK)
}

func (r *Runner) beginTopLevel(nodeID, nodeType string) {
	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	r.active = &activeExecution{nodeID: nodeID, nodeType: nodeType}
}

func (r *Runner) setActiveStage(nodeID, stageDir string) {
	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	if r.active != nil && r.active.nodeID == nodeID {
		r.active.stageDir = stageDir
	}
}

func (r *Runner) clearTopLevel(nodeID string) {
	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	if r.active != nil && r.active.nodeID == nodeID {
		r.active = nil
	}
}

func (s *controlServer) close() error {
	serverErr := s.server.Close()
	removeErr := os.Remove(s.socketPath)
	if os.IsNotExist(removeErr) {
		removeErr = nil
	}
	var temporaryErr error
	if s.temporaryRoot != "" {
		temporaryErr = os.RemoveAll(s.temporaryRoot)
	}
	return errors.Join(serverErr, removeErr, temporaryErr)
}

package engine

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/tylergannon/tractor/harness"
)

type timelineEvent map[string]any

type runStore struct {
	root  string
	state *engineState

	checkpointMu sync.Mutex
	timelineMu   sync.Mutex
}

type stage struct {
	Seq    uint64
	NodeID string
	Dir    string
	store  *runStore
}

func openRunStore(root string, state *engineState) (*runStore, error) {
	stagesRoot := filepath.Join(root, "stages")
	if err := os.MkdirAll(filepath.Join(stagesRoot, "latest"), 0o755); err != nil {
		return nil, fmt.Errorf("create run directory: %w", err)
	}
	highest, err := recoverStageSequence(stagesRoot)
	if err != nil {
		return nil, fmt.Errorf("recover stage sequence: %w", err)
	}
	state.mu.Lock()
	if highest > state.seq {
		state.seq = highest
	}
	state.mu.Unlock()
	return &runStore{root: root, state: state}, nil
}

// LoadCheckpoint reads the durable state needed to reconstruct a run.
func LoadCheckpoint(root string) (Checkpoint, error) {
	raw, err := os.ReadFile(filepath.Join(root, "checkpoint.json"))
	if err != nil {
		return Checkpoint{}, fmt.Errorf("read checkpoint: %w", err)
	}
	var checkpoint Checkpoint
	if err := json.Unmarshal(raw, &checkpoint); err != nil {
		return Checkpoint{}, fmt.Errorf("decode checkpoint: %w", err)
	}
	checkpoint.CompletedNodes = cloneSlice(checkpoint.CompletedNodes)
	checkpoint.NodeVisits = cloneMap(checkpoint.NodeVisits)
	checkpoint.NodeAttempts = cloneMap(checkpoint.NodeAttempts)
	checkpoint.Sessions = cloneMap(checkpoint.Sessions)
	return checkpoint, nil
}

func (s *runStore) saveCheckpoint(checkpoint Checkpoint) error {
	s.checkpointMu.Lock()
	defer s.checkpointMu.Unlock()

	checkpoint.Timestamp = time.Now().UTC()
	checkpoint.CompletedNodes = cloneSlice(checkpoint.CompletedNodes)
	checkpoint.NodeVisits = cloneMap(checkpoint.NodeVisits)
	checkpoint.NodeAttempts = cloneMap(checkpoint.NodeAttempts)
	checkpoint.Sessions = cloneMap(checkpoint.Sessions)
	raw, err := json.MarshalIndent(checkpoint, "", "  ")
	if err != nil {
		return fmt.Errorf("encode checkpoint: %w", err)
	}
	raw = append(raw, '\n')

	path := filepath.Join(s.root, "checkpoint.json")
	temporary := filepath.Join(s.root, ".checkpoint.json.tmp")
	if err := os.WriteFile(temporary, raw, 0o644); err != nil {
		return fmt.Errorf("write checkpoint: %w", err)
	}
	if err := os.Rename(temporary, path); err != nil {
		_ = os.Remove(temporary)
		return fmt.Errorf("replace checkpoint: %w", err)
	}
	return nil
}

func (s *runStore) appendTimeline(event timelineEvent) error {
	s.timelineMu.Lock()
	defer s.timelineMu.Unlock()
	file, err := os.OpenFile(filepath.Join(s.root, "timeline.jsonl"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("open timeline: %w", err)
	}
	encodeErr := json.NewEncoder(file).Encode(event)
	closeErr := file.Close()
	if encodeErr != nil {
		return fmt.Errorf("append timeline: %w", encodeErr)
	}
	if closeErr != nil {
		return fmt.Errorf("close timeline: %w", closeErr)
	}
	return nil
}

func (s *runStore) appendSteering(stageDir string, parts []harness.ContentPart) error {
	file, err := os.OpenFile(filepath.Join(stageDir, "steering.jsonl"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("open steering audit: %w", err)
	}
	encodeErr := json.NewEncoder(file).Encode(struct {
		Timestamp time.Time             `json:"timestamp"`
		Parts     []harness.ContentPart `json:"parts"`
	}{Timestamp: time.Now().UTC(), Parts: parts})
	closeErr := file.Close()
	if encodeErr != nil {
		return fmt.Errorf("append steering audit: %w", encodeErr)
	}
	if closeErr != nil {
		return fmt.Errorf("close steering audit: %w", closeErr)
	}
	return nil
}

func (s *runStore) allocateStage(nodeID string) (stage, error) {
	s.state.mu.Lock()
	defer s.state.mu.Unlock()
	sequence := s.state.seq + 1
	dir := filepath.Join(s.root, "stages", fmt.Sprintf("%06d-%s", sequence, nodeID))
	if err := os.Mkdir(dir, 0o755); err != nil {
		return stage{}, fmt.Errorf("create stage directory: %w", err)
	}
	s.state.seq = sequence
	return stage{Seq: sequence, NodeID: nodeID, Dir: dir, store: s}, nil
}

func (s stage) complete(outcome harness.Outcome) error {
	if err := writeJSON(filepath.Join(s.Dir, "outcome.json"), outcome); err != nil {
		return fmt.Errorf("write outcome: %w", err)
	}
	latest := filepath.Join(s.store.root, "stages", "latest", s.NodeID)
	temporary := latest + ".tmp"
	if err := os.Remove(temporary); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("prepare latest stage link: %w", err)
	}
	target := filepath.Join("..", filepath.Base(s.Dir))
	if err := os.Symlink(target, temporary); err != nil {
		return fmt.Errorf("create latest stage link: %w", err)
	}
	if err := os.Rename(temporary, latest); err != nil {
		_ = os.Remove(temporary)
		return fmt.Errorf("replace latest stage link: %w", err)
	}
	return nil
}

func (s stage) fail(runErr *harness.Error) error {
	if err := writeJSON(filepath.Join(s.Dir, "error.json"), runErr); err != nil {
		return fmt.Errorf("write stage error: %w", err)
	}
	return nil
}

func writeJSON(path string, value any) error {
	raw, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return err
	}
	raw = append(raw, '\n')
	return os.WriteFile(path, raw, 0o644)
}

func recoverStageSequence(stagesRoot string) (uint64, error) {
	entries, err := os.ReadDir(stagesRoot)
	if err != nil {
		return 0, err
	}
	var highest uint64
	for _, entry := range entries {
		if !entry.IsDir() || entry.Name() == "latest" {
			continue
		}
		dash := strings.IndexByte(entry.Name(), '-')
		if dash <= 0 {
			continue
		}
		sequence, parseErr := strconv.ParseUint(entry.Name()[:dash], 10, 64)
		if parseErr == nil && sequence > highest {
			highest = sequence
		}
	}
	return highest, nil
}

