type proofAdapter struct {
	name string
	run  func(harness.RunTurnInput) (harness.Result, *harness.Error)

	mu      sync.Mutex
	next    int
	created []string
	inputs  []harness.RunTurnInput
}

func (a *proofAdapter) CreateSession(_, _ string) (string, *harness.Error) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.next++
	sessionID := fmt.Sprintf("%s-%d", a.name, a.next)
	a.created = append(a.created, sessionID)
	return sessionID, nil
}

func (a *proofAdapter) RunTurn(input harness.RunTurnInput, _ harness.OnEvent) (harness.Result, *harness.Error) {
	a.mu.Lock()
	a.inputs = append(a.inputs, input)
	run := a.run
	a.mu.Unlock()
	return run(input)
}

func (*proofAdapter) Steer(string, []harness.ContentPart)   {}
func (*proofAdapter) Interrupt(string)                      {}
func (*proofAdapter) Compact(string, string) *harness.Error { return nil }

func (a *proofAdapter) createdSessions() []string {
	a.mu.Lock()
	defer a.mu.Unlock()
	return append([]string(nil), a.created...)
}

func (a *proofAdapter) inputsSnapshot() []harness.RunTurnInput {
	a.mu.Lock()
	defer a.mu.Unlock()
	return append([]harness.RunTurnInput(nil), a.inputs...)
}

func appendProofLine(path string, value map[string]string) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	if err := json.NewEncoder(file).Encode(value); err != nil {
		_ = file.Close()
		return err
	}
	return file.Close()
}

func readProofLines(t *testing.T, path string) []map[string]string {
	t.Helper()
	file, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer func() {
		if err := file.Close(); err != nil {
			t.Errorf("close proof log: %v", err)
		}
	}()
	var lines []map[string]string
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		var line map[string]string
		if err := json.Unmarshal(scanner.Bytes(), &line); err != nil {
			t.Fatal(err)
		}
		lines = append(lines, line)
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	return lines
}

func shortProofTempDir(t *testing.T) string {
	t.Helper()
	dir, err := os.MkdirTemp("/tmp", "tractor-proof-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := os.RemoveAll(dir); err != nil {
			t.Errorf("remove proof temp dir: %v", err)
		}
	})
	return dir
}

var _ harness.HarnessAdapter = (*proofAdapter)(nil)

func TestDefinitionProofExecutionScopeHasNoReplayFlag(t *testing.T) {
	typeOfScope := reflect.TypeOf(ExecutionScope{})
	fields := make([]string, typeOfScope.NumField())
	for index := range typeOfScope.NumField() {
		fields[index] = typeOfScope.Field(index).Name
	}
	if got := strings.Join(fields, ","); got != "Workdir,StageDir,Goal,Stop" {
		t.Fatalf("ExecutionScope exposes replay metadata: %s", got)
	}
}

package engine

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/lint"
)

type parallelHandler struct {
	runner *Runner
	state  *engineState
	store  *runStore
}

func (h *parallelHandler) Execute(node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (harness.Outcome, *harness.Error) {
	parallel, ok := node.(*graph.ParallelNode)
	if !ok {
		return harness.Outcome{}, terminalError(fmt.Sprintf("parallel handler cannot execute node type %s", node.NodeType()))
	}
	limit := 4
	if parallel.MaxParallel.Present {
		limit = parallel.MaxParallel.Value
	}
	if limit <= 0 {
		return harness.Outcome{}, terminalError("max_parallel must be positive")
	}

	join, err := parallelFanIn(*pipeline, parallel.ID)
	if err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}
	snapshot := h.state.snapshotCounters()
	succeeded := false
	defer func() {
		if !succeeded {
			h.state.restoreCounters(snapshot)
		}
	}()
	if scope.Stop.IsSet() {
		return harness.Outcome{}, interruptedError("stopped by operator")
	}
	parallelStarted := time.Now()
	if err := h.store.appendTimeline(timelineEvent{
		"type":         "ParallelStarted",
		"branch_count": len(offered),
	}); err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}

	indexOffset, err := segmentIndexOffset(h.store.root)
	if err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}
	frozen, err := freezeGitWorkspaceWithStop(scope.Workdir, scope.Stop)
	if err != nil {
		return harness.Outcome{}, parallelExecutionError(err)
	}
	branchIDs := make([]string, len(offered))
	for index, edge := range offered {
		branchIDs[index] = edge.To
	}
	worktrees, err := createBranchWorktreesWithStop(frozen, h.store.root, branchIDs, scope.Stop)
	if err != nil {
